    private val byKey = entries.associateBy { Triple(it.profile, it.datasetId, it.contentId) }

    init {
        require(entries.size == 405)
        require(byKey.size == 405)
        require(entries.count { it.kind == CanonicalContentKind.MONSTER } == 208)
        require(entries.count { it.kind == CanonicalContentKind.EQUIPMENT } == 54)
        require(entries.count { it.kind == CanonicalContentKind.SPELL } == 106)
        require(entries.count { it.kind == CanonicalContentKind.ENCOUNTER_TABLE } == 15)
        require(entries.count { it.kind == CanonicalContentKind.TREASURE_TYPE } == 22)
    }

    fun lookup(profile: RuleProfile, datasetId: String, contentId: String): CanonicalContentDescriptor? =
        byKey[Triple(profile, datasetId, contentId)]

    fun all(profile: RuleProfile, datasetId: String? = null): List<CanonicalContentDescriptor> =
        entries.asSequence()
            .filter { it.profile == profile }
            .filter { datasetId == null || it.datasetId == datasetId }
            .sortedWith(compareBy<CanonicalContentDescriptor>({ it.datasetId }, { it.contentId }))
            .toList()

    fun datasets(profile: RuleProfile): Set<String> =
        entries.asSequence().filter { it.profile == profile }.map { it.datasetId }.toSortedSet()
}
